package com.codeassess.ai.dto;

import com.fasterxml.jackson.annotation.JsonAlias;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * Encapsulates a structured batch of test cases generated by an AI model.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@JsonIgnoreProperties(ignoreUnknown = true)
public class AiTestCaseBatchResponse {

    @Builder.Default
    @JsonAlias({"test_cases", "testcases", "tests", "cases", "items", "data", "testCaseList"})
    private List<AiTestCaseDraftDto> testCases = new ArrayList<>();
}

